const allData = {{workflowparams:allData}} || {};
const isForceComplete = {{workflowparams:isForceComplete}} || 0;

const refDocType = allData.ref_doc_type || "";
const isLOT = refDocType === "Location Transfer" ? 1 : 0;
const isPT = refDocType === "Plant Transfer" ? 1 : 0;
const isMSI = refDocType === "Miscellaneous Issue" ? 1 : 0;

// A bundle-free flat list: the picking subform can arrive nested on an Edit read.
const flatten = (rows) =>
  (rows || []).flatMap((row) => {
    const { children, ...rest } = row || {};
    return [rest, ...(Array.isArray(children) ? children : [])];
  });
const items = flatten(allData.table_picking_items).filter(
  (r) => r && r.row_type !== "header"
);
const uniq = (a) => [...new Set(a.filter((v) => v !== null && v !== undefined && v !== ""))];

return {
  pickingId: allData.id || "",
  pickingNo: allData.sp_id || "",
  plantId: allData.plant_id || "",
  organizationId: allData.organization_id || "",
  refDocType, isLOT, isPT, isMSI,
  isForceComplete: isForceComplete ? 1 : 0,
  items,
  srcIds: uniq(items.map((i) => i.src_id)),
  srcLineIds: uniq(items.map((i) => i.src_line_id)),
};

const prep = {{node:code_node_SPprep.data}};
const confirmedBy = {{workflowparams:confirmed_by}} || "";
const setupRaw = {{node:get_node_SPsetup.data}};
const setup = Array.isArray(setupRaw) ? setupRaw[0] : setupRaw;
const allowFull = setup && setup.sp_allow_full_picking === 1 ? 1 : 0;

const round3 = (v) => Math.round((parseFloat(v) || 0) * 1000) / 1000;
const items = prep.items || [];

// picked_qty is captured in the Pick UOM; store_out_qty is the canonical order-UOM
// figure the movement consumes, converted with the factors the line already carries.
const toOrderUom = (row, qty) => {
  const ob = parseFloat(row.order_base_qty) || 0;
  const pb = parseFloat(row.picking_base_qty) || 0;
  if (!ob || !pb) return qty;
  return round3((qty * pb) / ob);
};

const records = [];
const updatedItems = [];
let allDone = 1;
let anyPicked = 0;

for (const row of items) {
  if (row.line_status === "Cancelled") { updatedItems.push(row); continue; }
  const pickedAlt = round3(row.picked_qty);
  const pickedOrder = toOrderUom(row, pickedAlt);
  const toPick = round3(row.qty_to_pick);
  let pending = round3(toPick - pickedOrder);
  if (pending < 0) pending = 0;

  let status = "Open";
  if (allowFull && pickedOrder > 0) { status = "Completed"; pending = 0; }
  else if (pending === 0) status = "Completed";
  else if (pickedOrder > 0) status = "In Progress";
  if (prep.isForceComplete === 1) { status = "Completed"; pending = 0; }

  if (status !== "Completed") allDone = 0;
  if (pickedOrder > 0) {
    anyPicked = 1;
    records.push({
      handling_unit_id: row.handling_unit_id || null,
      item_code: row.item_code, item_name: row.item_name || "",
      item_desc: row.item_desc || "", more_desc: row.more_desc || "",
      batch_no: row.batch_no || null, target_batch: row.target_batch || null,
      serial_numbers: row.serial_numbers || "",
      store_out_qty: pickedOrder.toFixed(3),
      picked_qty_alt: pickedAlt.toFixed(3),
      item_uom: row.item_uom, picked_uom: row.picking_uom || row.item_uom,
      source_bin: row.source_bin || null, remark: row.remark || "",
      confirmed_by: confirmedBy, confirmed_at: null,
      src_id: row.src_id || null, src_line_id: row.src_line_id || null,
      src_no: row.src_no || "",
    });
  }
  updatedItems.push(Object.assign({}, row, {
    line_status: status,
    pending_process_qty: pending.toFixed(3),
    picked_qty: pickedAlt.toFixed(3),
  }));
}

const headerStatus = allDone ? "Completed" : (anyPicked ? "In Progress" : "Created");

return {
  records, updatedItems, headerStatus,
  hasRecords: records.length > 0 ? 1 : 0,
  autoAdvance: setup && setup.sp_auto_advance === 1 ? 1 : 0,
  isCompleted: headerStatus === "Completed" ? 1 : 0,
};

// The three subtypes live in different collections; only one branch ran.
const lot = {{node:search_node_SPlinesLOT.data.data}};
const pt = {{node:search_node_SPlinesPT.data.data}};
const msi = {{node:search_node_SPlinesMSI.data.data}};
const pick = (x) => (Array.isArray(x) ? x : (x ? [x] : []));
const rows = pick(lot).concat(pick(pt)).concat(pick(msi));
return { rows, rowCount: rows.length };

const prep = {{node:code_node_SPprep.data}};
const recs = {{node:code_node_SPrecords.data}};
const raw = {{node:code_node_SPsrcLines.data.rows}};
const srcLines = Array.isArray(raw) ? raw : (raw ? [raw] : []);

const round3 = (v) => Math.round((parseFloat(v) || 0) * 1000) / 1000;
const keyOf = (bin, batch, hu) =>
  `${bin || "no-bin"}|${batch || "no-batch"}|${hu || "no-hu"}`;

// What was actually picked, per source line and per physical origin.
const pickedByLine = {};
for (const r of recs.records || []) {
  const lid = String(r.src_line_id || "");
  if (!lid) continue;
  pickedByLine[lid] = pickedByLine[lid] || {};
  const k = keyOf(r.source_bin, r.batch_no, r.handling_unit_id);
  pickedByLine[lid][k] = round3((pickedByLine[lid][k] || 0) + parseFloat(r.store_out_qty));
}

const lineUpdates = [];
const errors = [];

for (const line of srcLines) {
  const picked = pickedByLine[String(line.id)];
  if (!picked) continue;

  let entries = [];
  try { entries = JSON.parse(line.temp_qty_data || "[]"); } catch (e) { entries = []; }
  if (!Array.isArray(entries)) entries = [];

  // Rewrite each staged allocation down to what the picker actually pulled from
  // that exact bin/batch/HU. The pick never relocates stock, so only the quantity
  // changes; category, UOM and dates are preserved from the original entry.
  const rebuilt = [];
  const remaining = Object.assign({}, picked);
  for (const e of entries) {
    const k = keyOf(e.location_id, e.batch_id, e.handling_unit_id);
    const avail = remaining[k];
    if (avail === undefined || avail <= 0) continue;
    const take = Math.min(round3(e.sm_quantity), avail);
    if (take <= 0) continue;
    remaining[k] = round3(avail - take);
    rebuilt.push(Object.assign({}, e, { sm_quantity: take }));
  }
  const leftover = Object.keys(remaining).filter((k) => remaining[k] > 0.0005);
  if (leftover.length > 0) {
    errors.push({
      line_id: line.id,
      message: "Picked quantity has no matching staged allocation at " + leftover.join(", "),
    });
    continue;
  }
  if (rebuilt.length === 0) continue;

  lineUpdates.push({
    id: line.id,
    temp_qty_data: JSON.stringify(rebuilt),
    prev_temp_qty_data: line.temp_qty_data || "",
    picking_status: "Completed",
  });
}

return {
  lineUpdates,
  hasLineUpdates: lineUpdates.length > 0 ? 1 : 0,
  errors,
  hasError: errors.length > 0 ? 1 : 0,
  errorMessage: errors.length > 0 ? errors[0].message : "",
};
